function validate(input) {
  const [arr] = input;
  if (!Array.isArray(arr)) return 'arr must be an array.';
  const stack = [[arr, 1]];
  while (stack.length) {
    const [items, level] = stack.pop();
    for (const item of items) {
      if (Array.isArray(item)) {
        if (level >= 10) return 'Nest arrays at most 10 levels deep, counting arr itself.';
        stack.push([item, level + 1]);
      } else if (!Number.isInteger(item) || item < 0 || item > 100000) return 'arr holds only integers from 0 to 10^5 and arrays of them.';
    }
  }
  return null;
}

