function adapt(input, solve, kit) {
  const [arr] = input, values = [];
  const gen = solve(arr);
  if (!gen || typeof gen.next !== 'function') throw new Error('inorderTraversal must return a generator object.');
  kit.trace('inorderTraversal(arr) creates the generator');
  while (true) {
    const step = gen.next();
    if (!step || typeof step !== 'object') throw new Error('next() must return { value, done }.');
    if (step.done) {
      kit.trace('gen.next() reports done');
      break;
    }
    if (typeof step.value !== 'number') throw new Error('Each value produced must be an integer from arr.');
    if (values.length >= 20000) throw new Error('The generator produces more values than arr holds.');
    kit.trace(`gen.next() yields ${step.value}`);
    values.push(step.value);
  }
  return values;
}

