function* inorderTraversal(arr) {
  // Build the flat copy the problem suggests avoiding: remove one level of brackets until none are left.
  let items = arr;
  while (items.some((item) => Array.isArray(item))) items = [].concat(...items);
  for (const value of items) yield value;
}

