function generate(rand, size) {
  const small = size === 'small', maxLevel = small ? 4 : 10;
  let budget = small ? 10 : 2500;
  const number = () => rand() < 0.1 ? [0, 100000][Math.floor(rand() * 2)] : Math.floor(rand() * (small ? 10 : 100001));
  // Builds an array at the given nesting level (arr itself is level 1).
  const build = (level, length) => {
    const items = [];
    for (let i = 0; i < length && budget > 0; i++) {
      budget--;
      if (level < maxLevel && rand() < (small ? 0.35 : 0.15)) items.push(build(level + 1, Math.floor(rand() * (small ? 4 : 12))));
      else items.push(number());
    }
    return items;
  };
  const arr = build(1, small ? Math.floor(rand() * 6) : 1200);
  if (!small) {
    // One chain that reaches the deepest allowed level.
    let chain = [number()];
    for (let level = 9; level > 1; level--) chain = [chain];
    arr.splice(Math.floor(rand() * (arr.length + 1)), 0, chain);
  }
  return [arr];
}
